    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABC</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span>، و <span dir=\"ltr\" class=\"expr pt\">AB̂C = 51°.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 198 230\" width=\"198\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30.0\" y1=\"200.0\" x2=\"167.7\" y2=\"200.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"167.7\" y1=\"200.0\" x2=\"30.0\" y2=\"30.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"30.0\" y1=\"30.0\" x2=\"30.0\" y2=\"200.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><path d=\"M 52.0 200.0 A 22 22 0 0 0 30.0 178.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"54.7\" y=\"179.3\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">90°</text><path d=\"M 153.8 182.9 A 22 22 0 0 0 145.7 200.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"136.1\" y=\"188.9\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">51°</text><path d=\"M 30.0 52.0 A 22 22 0 0 0 43.8 47.1\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"30.0\" cy=\"200.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"21.2\" y=\"214.9\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"167.7\" cy=\"200.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"179.6\" y=\"211.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"30.0\" cy=\"30.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"24.7\" y=\"21.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text></svg><br>أحسب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 51°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 51°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 51°) = 39°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 39°</span>"}],
